import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { describe, expect, it, vi } from "vitest";
import statuslineExtension, { extractSkillName, getActivityLabel } from "../extensions/index.js";

const createMockPi = () => ({
  on: vi.fn(),
  getThinkingLevel: vi.fn(() => "medium"),
  exec: vi.fn(async () => ({ code: 1, stdout: "", stderr: "", killed: false })),
  getCommands: vi.fn(() => [{ name: "release", source: "skill" }]),
  registerTool: vi.fn(),
});

describe("pi-statusline extension", () => {
  it("registers expected event handlers", () => {
    const mockPi = createMockPi();
    statuslineExtension(mockPi as unknown as ExtensionAPI);

    const eventNames = mockPi.on.mock.calls.map(([name]) => name);
    expect(eventNames).toEqual(
      expect.arrayContaining([
        "session_start",
        "agent_start",
        "turn_start",
        "message_start",
        "message_update",
        "message_end",
        "tool_execution_start",
        "tool_execution_update",
        "tool_execution_end",
        "model_select",
        "agent_end",
        "input",
        "session_shutdown",
      ]),
    );
  });

  it("registers /statusline tool in UI mode", async () => {
    const mockPi = createMockPi();
    statuslineExtension(mockPi as unknown as ExtensionAPI);

    const sessionStartHandler = mockPi.on.mock.calls.find(([name]) => name === "session_start")?.[1];
    await sessionStartHandler?.(
      {},
      {
        cwd: "/tmp/project",
        hasUI: true,
        model: { id: "opus", contextWindow: 1_000_000 },
        sessionManager: { getBranch: () => [] },
        getContextUsage: () => ({ percent: 11 }),
        ui: { setFooter: vi.fn() },
      },
    );

    expect(mockPi.registerTool).toHaveBeenCalledTimes(1);
    expect(mockPi.registerTool).toHaveBeenCalledWith(
      expect.objectContaining({
        name: "statusline",
        parameters: expect.any(Object),
      }),
    );
  });

  it("extracts skill names from explicit skill commands", () => {
    expect(extractSkillName("/skill:release", [])).toBe("release");
  });

  it("extracts skill names from registered skill commands", () => {
    expect(extractSkillName("/release", [{ name: "release", source: "skill" }])).toBe("release");
  });

  it("ignores non-skill slash commands", () => {
    expect(extractSkillName("/model", [{ name: "release", source: "skill" }])).toBeNull();
  });

  it("formats activity labels", () => {
    expect(getActivityLabel("idle")).toBe("Act: idle");
    expect(getActivityLabel("tool", "bash", 2)).toBe("Act: bash x2");
  });

  it("registers a custom footer on session_start", async () => {
    const mockPi = createMockPi();
    statuslineExtension(mockPi as unknown as ExtensionAPI);

    const sessionStartHandler = mockPi.on.mock.calls.find(([name]) => name === "session_start")?.[1];
    const setFooter = vi.fn();
    await sessionStartHandler?.(
      {},
      {
        cwd: "/tmp/project",
        hasUI: true,
        model: { id: "opus", contextWindow: 1_000_000 },
        sessionManager: { getBranch: () => [] },
        getContextUsage: () => ({ percent: 11 }),
        ui: { setFooter },
      },
    );

    expect(setFooter).toHaveBeenCalledTimes(1);
  });
});

import { describe, expect, it, vi } from "vitest";
import { createUiOnlyHandler } from "../extensions/ui-mode.js";

describe("UI-mode event helpers", () => {
  it("skips handlers when UI is unavailable", async () => {
    const handler = vi.fn();
    const uiOnly = createUiOnlyHandler(handler);

    const result = await uiOnly({ type: "event" }, { hasUI: false });

    expect(result).toBeUndefined();
    expect(handler).not.toHaveBeenCalled();
  });

  it("runs handlers when UI is available", async () => {
    const handler = vi.fn(async () => "handled");
    const uiOnly = createUiOnlyHandler(handler);

    const result = await uiOnly({ type: "event" }, { hasUI: true });

    expect(result).toBe("handled");
    expect(handler).toHaveBeenCalledOnce();
  });

  it("treats stale context access like an unavailable UI", async () => {
    const handler = vi.fn();
    const uiOnly = createUiOnlyHandler(handler);
    const staleCtx = {
      get hasUI() {
        throw new Error("This extension ctx is stale after session replacement or reload");
      },
    };

    await expect(Promise.resolve(uiOnly({ type: "event" }, staleCtx))).resolves.toBeUndefined();
    expect(handler).not.toHaveBeenCalled();
  });

  it("rethrows non-stale UI availability failures", async () => {
    const handler = vi.fn();
    const uiOnly = createUiOnlyHandler(handler);
    const brokenCtx = {
      get hasUI() {
        throw new Error("boom");
      },
    };

    await expect(uiOnly({ type: "event" }, brokenCtx)).rejects.toThrow("boom");
    expect(handler).not.toHaveBeenCalled();
  });

  it("swallows stale async handler failures", async () => {
    const handler = vi.fn(async () => {
      await Promise.resolve();
      throw new Error("This extension ctx is stale after session replacement or reload");
    });
    const uiOnly = createUiOnlyHandler(handler);

    await expect(uiOnly({ type: "event" }, { hasUI: true })).resolves.toBeUndefined();
    expect(handler).toHaveBeenCalledOnce();
  });

  it("rethrows non-stale handler failures", async () => {
    const handler = vi.fn(async () => {
      throw new Error("boom");
    });
    const uiOnly = createUiOnlyHandler(handler);

    await expect(uiOnly({ type: "event" }, { hasUI: true })).rejects.toThrow("boom");
  });
});

import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  extractStatuslineConfig,
  getStatuslineConfigPaths,
  isValidHexColor,
  loadStatuslinePalette,
  resolvePalette,
  sanitizePaletteInput,
} from "../extensions/config.js";
import { defaultPalette } from "../extensions/palette.js";

const tempDirs: string[] = [];

async function createTempDir() {
  const dir = await mkdtemp(join(tmpdir(), "pi-statusline-config-"));
  tempDirs.push(dir);
  return dir;
}

afterEach(async () => {
  await Promise.all(tempDirs.splice(0).map(async (dir) => rm(dir, { recursive: true, force: true })));
});

describe("pi-statusline config helpers", () => {
  it("validates hex colors", () => {
    expect(isValidHexColor("#008787")).toBe(true);
    expect(isValidHexColor("#abc")).toBe(false);
    expect(isValidHexColor("teal")).toBe(false);
  });

  it("sanitizes palette input", () => {
    expect(sanitizePaletteInput({ model: "#008787", repo: "bad", extra: "#ffffff" } as never)).toEqual({
      model: "#008787",
    });
  });

  it("extracts the statusline config namespace", () => {
    expect(extractStatuslineConfig({ "pi-statusline": { palette: { model: "#008787" } } })).toEqual({
      palette: { model: "#008787" },
    });
    expect(extractStatuslineConfig({})).toBeNull();
  });

  it("resolves project palette overrides over global and default values", () => {
    const palette = resolvePalette(
      { palette: { model: "#111111", repo: "#222222" } },
      { palette: { repo: "#333333", activity: "#444444" } },
    );

    expect(palette.model).toBe("#111111");
    expect(palette.repo).toBe("#333333");
    expect(palette.activity).toBe("#444444");
    expect(palette.thinking).toBe(defaultPalette.thinking);
  });

  it("returns standard global and project config paths", () => {
    expect(getStatuslineConfigPaths("/tmp/project", "/tmp/home")).toEqual({
      globalPath: "/tmp/home/.pi/agent/settings.json",
      projectPath: "/tmp/project/.pi/settings.json",
    });
  });

  it("loads palette overrides from settings files", async () => {
    const homeDir = await createTempDir();
    const cwd = await createTempDir();

    await mkdir(join(homeDir, ".pi", "agent"), { recursive: true });
    await mkdir(join(cwd, ".pi"), { recursive: true });

    await writeFile(
      join(homeDir, ".pi", "agent", "settings.json"),
      JSON.stringify({ "pi-statusline": { palette: { model: "#111111", repo: "#222222" } } }),
    );
    await writeFile(
      join(cwd, ".pi", "settings.json"),
      JSON.stringify({ "pi-statusline": { palette: { repo: "#333333", activity: "#444444" } } }),
    );

    const palette = await loadStatuslinePalette(cwd, homeDir);

    expect(palette.model).toBe("#111111");
    expect(palette.repo).toBe("#333333");
    expect(palette.activity).toBe("#444444");
  });

  it("ignores invalid settings and warns once per bad file", async () => {
    const homeDir = await createTempDir();
    const cwd = await createTempDir();
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    await mkdir(join(homeDir, ".pi", "agent"), { recursive: true });
    await mkdir(join(cwd, ".pi"), { recursive: true });

    await writeFile(join(homeDir, ".pi", "agent", "settings.json"), "{not-json");
    await writeFile(
      join(cwd, ".pi", "settings.json"),
      JSON.stringify({ "pi-statusline": { palette: { model: "bad", activity: "#444444" } } }),
    );

    const palette = await loadStatuslinePalette(cwd, homeDir);

    expect(palette.model).toBe(defaultPalette.model);
    expect(palette.activity).toBe("#444444");
    expect(warnSpy).toHaveBeenCalledTimes(1);
  });
});

